package ru.tuvio.tools.dlnaclient;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class MediaDetailsTest {
 @Test public void durationSupportsFractionalSeconds(){assertEquals(3723456,MediaDetails.duration("01:02:03.456"));assertEquals(0,MediaDetails.duration("bad"));}
 @Test public void dateUnderstandsOffsets(){assertEquals(MediaDetails.date("2024-01-01T00:00:00Z"),MediaDetails.date("2024-01-01T03:00:00+03:00"));assertEquals(0,MediaDetails.date("bad"));}
 @Test public void subtitleDetectionDoesNotMatchMovieNames(){assertNull(MediaDetails.subtitleMime("video/x-matroska","http://example.invalid/Assassin.mkv"));assertEquals("text/x-ssa",MediaDetails.subtitleMime("ass","http://example.invalid/123"));assertEquals("application/x-subrip",MediaDetails.subtitleMime("text/srt","http://example.invalid/abc"));}
 @Test public void matchingSidecarsIncludesLanguageAndDeduplicates(){DmsItem v=new DmsItem("1","0","Film.mkv","video/x-matroska","http://example.invalid/1",5,false,null,null);DmsItem s=new DmsItem("2","0","Film.ru.srt","text/srt","http://example.invalid/2",2,false,null,null);MediaDetails.attachSidecars(Arrays.asList(v,s));MediaDetails.attachSidecars(Arrays.asList(v,s));assertEquals(1,v.subtitles.size());assertEquals("ru",v.subtitles.get(0).language);}
 @Test public void unrelatedSubtitlesDoNotAttach(){DmsItem v=new DmsItem("1","0","Film.mkv","video/x-matroska","http://example.invalid/1",5,false,null,null);DmsItem s=new DmsItem("2","0","Other.srt","text/srt","http://example.invalid/2",2,false,null,null);MediaDetails.attachSidecars(Arrays.asList(v,s));assertTrue(v.subtitles.isEmpty());}
 @Test public void browseReadsTagsDurationAndCaptionLinks()throws Exception{String didl=UpnpTest.didl("<item id='1' parentID='0' xmlns:s='http://www.sec.co.kr/'><t:title>Film</t:title><t:date>2024-01-01</t:date><c:genre>Drama</c:genre><res duration='01:02:03.5' size='100' protocolInfo='http-get:*:video/mp4:*'>/film.mp4</res><s:CaptionInfoEx s:type='srt'>/film.srt</s:CaptionInfoEx></item>");DmsItem i=UpnpXml.browse(UpnpTest.soap(didl,1,1),"http://example.invalid/desc.xml").items.get(0);assertEquals(3723500,i.durationMs);assertEquals("Drama",i.genre);assertEquals("2024-01-01",i.date);assertEquals("http://example.invalid/film.mp4",i.url);assertEquals(1,i.subtitles.size());}
}
